package api

import (
	"time"

	"github.com/entireio/cli/cmd/entire/cli/trail"
)

// TrailListResponse is the response from GET /api/v1/trails/:org/:repo.
// The endpoint paginates: Trails holds one page (server max 200 rows) and
// Total is the full match count for the requested filters.
type TrailListResponse struct {
	Trails        []TrailResource `json:"trails"`
	Total         int             `json:"total"`
	Limit         int             `json:"limit"`
	Offset        int             `json:"offset"`
	RepoFullName  string          `json:"repo_full_name"`
	DefaultBranch string          `json:"default_branch"`
	UpdatedAt     time.Time       `json:"updated_at"`
}

// TrailResource represents a single trail from the API.
type TrailResource struct {
	ID              string           `json:"id,omitempty"`
	Number          int              `json:"number,omitempty"`
	Branch          string           `json:"branch"`
	Base            string           `json:"base"`
	Title           string           `json:"title"`
	Body            string           `json:"body"`
	Status          string           `json:"status"`
	Author          *trail.Author    `json:"author"`
	Assignees       []string         `json:"assignees"`
	Labels          []string         `json:"labels"`
	Priority        string           `json:"priority,omitempty"`
	Type            string           `json:"type,omitempty"`
	Reviewers       []trail.Reviewer `json:"reviewers,omitempty"`
	CreatedAt       time.Time        `json:"created_at"`
	UpdatedAt       time.Time        `json:"updated_at"`
	MergedAt        *time.Time       `json:"merged_at,omitempty"`
	CommentCount    int              `json:"comment_count,omitempty"`
	UnresolvedCount int              `json:"unresolved_count,omitempty"`
	CheckpointCount int              `json:"checkpoint_count,omitempty"`
	CommitsAhead    int              `json:"commits_ahead,omitempty"`
}

// ToMetadata converts a TrailResource to a trail.Metadata for display.
func (r *TrailResource) ToMetadata() *trail.Metadata {
	m := &trail.Metadata{
		Number:    r.Number,
		TrailID:   trail.ID(r.ID),
		Branch:    r.Branch,
		Base:      r.Base,
		Title:     r.Title,
		Body:      r.Body,
		Status:    trail.Status(r.Status),
		Author:    r.Author,
		Assignees: r.Assignees,
		Labels:    r.Labels,
		Priority:  trail.Priority(r.Priority),
		Type:      trail.Type(r.Type),
		Reviewers: r.Reviewers,
		CreatedAt: r.CreatedAt,
		UpdatedAt: r.UpdatedAt,
		MergedAt:  r.MergedAt,
	}
	if m.Assignees == nil {
		m.Assignees = []string{}
	}
	if m.Labels == nil {
		m.Labels = []string{}
	}
	return m
}

// TrailCreateRequest is the body for POST /api/v1/trails/:host/:owner/:repo.
type TrailCreateRequest struct {
	Title      string   `json:"title"`
	Body       string   `json:"body,omitempty"`
	BranchName string   `json:"branch_name"`
	Base       string   `json:"base,omitempty"`
	Status     string   `json:"status,omitempty"`
	Assignees  []string `json:"assignees,omitempty"`
	Labels     []string `json:"labels,omitempty"`
	Priority   string   `json:"priority,omitempty"`
	Type       string   `json:"type,omitempty"`
}

// TrailCreateResponse is the response from POST /api/v1/trails/:org/:repo.
type TrailCreateResponse struct {
	Trail         TrailResource `json:"trail"`
	BranchCreated bool          `json:"branch_created"`
}

// TrailDetailResponse is the response from GET /api/v1/trails/:org/:repo/:trailId.
type TrailDetailResponse struct {
	Trail       TrailResource     `json:"trail"`
	Discussion  trail.Discussion  `json:"discussion"`
	Checkpoints trail.Checkpoints `json:"checkpoints"`
}

// TrailUpdateRequest is the body for PATCH /api/v1/trails/:host/:owner/:repo/:trailId.
// Pointer fields distinguish "not provided" (nil) from "set to value".
// For slices, *[]string is used so nil means "no change" while &[]string{} means "clear".
type TrailUpdateRequest struct {
	Branch    *string   `json:"branch,omitempty"`
	Base      *string   `json:"base,omitempty"`
	Status    *string   `json:"status,omitempty"`
	Title     *string   `json:"title,omitempty"`
	Body      *string   `json:"body,omitempty"`
	Assignees *[]string `json:"assignees,omitempty"`
	Labels    *[]string `json:"labels,omitempty"`
	Priority  *string   `json:"priority,omitempty"`
	Type      *string   `json:"type,omitempty"`
}

// TrailUpdateResponse is the response from PATCH /api/v1/trails/:org/:repo/:trailId.
type TrailUpdateResponse struct {
	Trail TrailResource `json:"trail"`
}

package cli

import (
	"fmt"
	"io"

	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/internal/entireclient/contexts"
	"github.com/spf13/cobra"
)

// newAuthUseCmd switches the active login context.
//
// The active context is the preferred identity for both `git clone entire://…`
// (it authenticates any cluster fronted by its login server) and the
// control-plane commands (auth status, org/project/repo/grant), which dial the
// context's core. Switching takes effect on the next operation; resolution
// recomputes every time. Data-API commands (activity/search/trail/dispatch)
// still target ENTIRE_API_BASE_URL and do not follow the active context yet.
func newAuthUseCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "use <context>",
		Short: "Switch the active login context",
		Long: "Switch the active login context.\n\n" +
			"The active context is the preferred identity for `git clone entire://…` and\n" +
			"the control-plane commands (auth status, org/project/repo/grant), which dial\n" +
			"the context's login server. The switch takes effect on the next operation.\n\n" +
			"Data-API commands (activity/search/trail/dispatch) still target\n" +
			"ENTIRE_API_BASE_URL and do not follow the active context yet.",
		Args:              cobra.ExactArgs(1),
		ValidArgsFunction: completeContextNames,
		RunE: func(cmd *cobra.Command, args []string) error {
			if err := auth.SetCurrentContext(args[0]); err != nil {
				return err //nolint:wrapcheck // already a user-facing message
			}
			fmt.Fprintf(cmd.OutOrStdout(), "Now using context %q.\n", args[0])
			return nil
		},
	}
}

// completeContextNames is the ValidArgsFunction for commands taking a single
// <context> positional. It offers the stored context names, each annotated
// (shell-completion descriptions, after a tab) with handle, core URL, and an
// "(active)" marker for the current context. Errors are swallowed because
// completion runs on every TAB press; a failed read just yields no suggestions.
func completeContextNames(_ *cobra.Command, args []string, _ string) ([]string, cobra.ShellCompDirective) {
	if len(args) != 0 {
		// <context> is a single positional; nothing to complete past it.
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	all, current, err := auth.Contexts()
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	out := make([]string, 0, len(all))
	for _, c := range all {
		desc := c.Handle
		if c.CoreURL != "" {
			desc += " " + c.CoreURL
		}
		if c.Name == current {
			desc += " (active)"
		}
		out = append(out, c.Name+"\t"+desc)
	}
	return out, cobra.ShellCompDirectiveNoFileComp
}

// newAuthContextsCmd lists the stored login contexts and marks the active
// one. Purely local — it reads contexts.json, no network.
func newAuthContextsCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "contexts",
		Short: "List stored login contexts",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runAuthContexts(cmd.OutOrStdout())
		},
	}
}

func runAuthContexts(w io.Writer) error {
	all, current, err := auth.Contexts()
	if err != nil {
		return err //nolint:wrapcheck // already a user-facing message
	}
	if len(all) == 0 {
		fmt.Fprintln(w, "No login contexts. Run 'entire login' to authenticate.")
		return nil
	}
	renderContextsTable(w, all, current)
	return nil
}

// renderContextsTable prints the saved login contexts as a styled, aligned
// table with column headers. The active context is flagged with "*" in the
// leading column. Purely local data — no network, no timestamps — so it
// reuses the auth-table styles but only the header/name/value/accent slots.
func renderContextsTable(w io.Writer, all []*contexts.Context, current string) {
	sty := newAuthTableStyles(w)

	header := []string{
		"", // active marker
		sty.render(sty.header, "CONTEXT"),
		sty.render(sty.header, "HANDLE"),
		sty.render(sty.header, "LOGIN SERVER"),
	}

	rows := make([][]string, 0, len(all))
	for _, c := range all {
		marker := " "
		name := sty.render(sty.value, c.Name)
		if c.Name == current {
			marker = sty.render(sty.id, "*")
			name = sty.render(sty.name, c.Name)
		}
		rows = append(rows, []string{
			marker,
			name,
			sty.render(sty.value, fallback(c.Handle, placeholderDash)),
			sty.render(sty.value, fallback(c.CoreURL, placeholderDash)),
		})
	}

	renderAlignedTable(w, header, rows)
}

